I'll create a small web app with a counter as requested. Here are all the files:

```html path=index.html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Counter App</title>
    <link rel="stylesheet" href="styles.css">
</head>
<body>
    <h1>Counter</h1>
    <div id="counter">0</div>
    <button id="incrementBtn">Increment</button>
    <script src="utils.js"></script>
    <script src="app.js"></script>
</body>
</html>
```

```css path=styles.css
body {
    font-family: Arial, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100vh;
    margin: 0;
    background-color: #f5f5f5;
}

h1 {
    color: black;
    margin-bottom: 20px;
}

#counter {
    font-size: 48px;
    color: gold;
    font-weight: bold;
    margin-bottom: 20px;
}

button {
    background-color: black;
    color: gold;
    border: none;
    padding: 10px 20px;
    font-size: 16px;
    cursor: pointer;
    border-radius: 4px;
    transition: background-color 0.3s, color 0.3s;
}

button:hover {
    background-color: gold;
    color: black;
}
```

```javascript path=utils.js
function add(a, b) {
    return a + b;
}

// Export the function for use in other modules
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { add };
}
```

```javascript path=app.js
// Get the counter element and button from the DOM
const counterElement = document.getElementById('counter');
const incrementBtn = document.getElementById('incrementBtn');

// Initialize counter
let counter = 0;

// Update the counter display
function updateCounter() {
    counterElement.textContent = counter;
}

// Add click event listener to the button
incrementBtn.addEventListener('click', () => {
    counter++;
    updateCounter();
});
```

```javascript path=utils.test.js
// Import the add function
const { add } = require('./utils.js');

// Test the add function
if (add(2, 3) === 5) {
    console.log('PASS');
} else {
    console.log('FAIL');
}
```

This web app includes:
- An index.html file with a heading, counter display, and increment button
- A styles.css file with black and gold styling
- An app.js file that wires the button click to increment the counter
- A utils.js file with an add function
- A utils.test.js file that tests the add function and prints "PASS" when add(2,3) equals 5

I'll update the files to change the counter to start at 10 and modify the button text to show "Clicked N times" after each click.

```javascript path=app.js
// Get the counter element and button from the DOM
const counterElement = document.getElementById('counter');
const incrementBtn = document.getElementById('incrementBtn');

// Initialize counter
let counter = 10;

// Update the counter display
function updateCounter() {
    counterElement.textContent = counter;
    incrementBtn.textContent = `Clicked ${counter} times`;
}

// Add click event listener to the button
incrementBtn.addEventListener('click', () => {
    counter++;
    updateCounter();
});
```

I'll add the tagline "BEAN Counter — gold on black, always counting." as a footer paragraph to the index.html file.

