I'll add a reset button next to the counter that sets the count back to 10. Here are the updated files:

```html path=index.html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Counter App</title>
    <link rel="stylesheet" href="styles.css">
</head>
<body>
    <h1>Counter</h1>
    <div id="counter">10</div>
    <div class="button-container">
        <button id="incrementBtn">Clicked 0 times</button>
        <button id="resetBtn">Reset</button>
    </div>
    <p class="tagline">BEAN Counter — gold on black, always counting.</p>
    <script src="utils.js"></script>
    <script src="app.js"></script>
</body>
</html>
```

```javascript path=app.js
// Get the counter element and buttons from the DOM
const counterElement = document.getElementById('counter');
const incrementBtn = document.getElementById('incrementBtn');
const resetBtn = document.getElementById('resetBtn');

// Initialize counter
let counter = 10;

// Update the counter display
function updateCounter() {
    counterElement.textContent = counter;
    incrementBtn.textContent = `Clicked ${counter} times`;
}

// Add click event listener to the increment button
incrementBtn.addEventListener('click', () => {
    counter++;
    updateCounter();
});

// Add click event listener to the reset button
resetBtn.addEventListener('click', () => {
    counter = 10;
    updateCounter();
});

// Initialize the display
updateCounter();
```

